import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';

export interface Frontmatter {
  title?: string;
  date?: string;
  tags?: string[];
  [key: string]: unknown;
}

export interface Page {
  slug: string;
  title: string;
  date?: string;
  tags: string[];
  html: string;
  sourcePath: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

export interface Site {
  pages: Page[];
  outputDir: string;
}

const DEFAULT_CONTENT_DIR = 'content';
const DEFAULT_OUTPUT_DIR = 'dist';

// Matches a YAML frontmatter block. The opening `---` may be preceded only by
// optional leading whitespace so that marked never sees the delimiters.
const FRONTMATTER_REGEX = /^\s*---[ \t]*\r?\n([\s\S]*?)\r?\n---[ \t]*\r?\n?/;

/**
 * Split raw markdown into frontmatter data and the markdown body.
 *
 * The frontmatter block is stripped manually with a regex before the body is
 * handed to `marked`, otherwise `marked` renders the `---` delimiters as a
 * literal horizontal rule. gray-matter is used only to parse the YAML data.
 */
export function splitFrontmatter(raw: string): { data: Frontmatter; body: string } {
  const match = raw.match(FRONTMATTER_REGEX);
  if (!match) {
    return { data: {}, body: raw };
  }

  let data: Frontmatter = {};
  try {
    data = (matter(match[0]).data as Frontmatter) ?? {};
  } catch {
    data = {};
  }

  const body = raw.slice(match[0].length);
  return { data, body };
}

/**
 * Parse raw markdown (with optional frontmatter) into frontmatter data and
 * rendered HTML. The returned HTML is a document fragment (no <html>/<body>).
 */
export function parseMarkdown(raw: string): { frontmatter: Frontmatter; html: string } {
  const { data, body } = splitFrontmatter(raw);
  const html = marked.parse(body, { async: false }) as string;
  return { frontmatter: data, html };
}

export function escapeHtml(input: string): string {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function normalizeTags(tags: unknown): string[] {
  if (Array.isArray(tags)) {
    return tags.map((t) => String(t));
  }
  if (typeof tags === 'string') {
    return tags
      .split(',')
      .map((t) => t.trim())
      .filter((t) => t.length > 0);
  }
  return [];
}

function defaultTitle(slug: string): string {
  return slug
    .split(/[/\\-]/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

function listMarkdownFiles(dir: string): string[] {
  if (!fs.existsSync(dir)) {
    return [];
  }
  const results: string[] = [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...listMarkdownFiles(full));
    } else if (entry.isFile() && entry.name.toLowerCase().endsWith('.md')) {
      results.push(full);
    }
  }
  return results;
}

function deriveSlug(filePath: string, contentDir: string): string {
  const relative = path.relative(contentDir, filePath);
  const parsed = path.parse(relative);
  return path.join(parsed.dir, parsed.name).split(path.sep).join('/');
}

function renderPage(page: Page, pages: Page[]): string {
  const meta: string[] = [];
  if (page.date) {
    meta.push(`<p class="date">${escapeHtml(page.date)}</p>`);
  }
  if (page.tags.length > 0) {
    const tagItems = page.tags
      .map((tag) => `<li>${escapeHtml(tag)}</li>`)
      .join('');
    meta.push(`<ul class="tags">${tagItems}</ul>`);
  }

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>${escapeHtml(page.title)}</title>
</head>
<body>
<h1>${escapeHtml(page.title)}</h1>
${meta.join('\n')}
<div class="content">
${page.html}
</div>
</body>
</html>
`;
}

function renderIndex(pages: Page[]): string {
  const items = pages
    .map((page) => {
      const date = page.date ? ` <span class="date">${escapeHtml(page.date)}</span>` : '';
      return `<li><a href="${escapeHtml(page.slug)}.html">${escapeHtml(
        page.title
      )}</a>${date}</li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Index</title>
</head>
<body>
<h1>All Pages</h1>
<ul>
${items}
</ul>
</body>
</html>
`;
}

/**
 * Build the static site: read markdown from contentDir and write HTML files
 * (one per page plus an index.html) into outputDir.
 */
export function buildSite(options: BuildOptions): Site {
  const contentDir = path.resolve(options.contentDir ?? DEFAULT_CONTENT_DIR);
  const outputDir = path.resolve(options.outputDir ?? DEFAULT_OUTPUT_DIR);

  const files = listMarkdownFiles(contentDir).sort();

  const pages: Page[] = files.map((file) => {
    const raw = fs.readFileSync(file, 'utf8');
    const { frontmatter, html } = parseMarkdown(raw);
    const slug = deriveSlug(file, contentDir);
    return {
      slug,
      title: frontmatter.title ?? defaultTitle(slug),
      date: frontmatter.date != null ? String(frontmatter.date) : undefined,
      tags: normalizeTags(frontmatter.tags),
      html,
      sourcePath: file,
    };
  });

  pages.sort((a, b) => {
    if (a.date && b.date) {
      return b.date.localeCompare(a.date);
    }
    if (a.date) return -1;
    if (b.date) return 1;
    return a.title.localeCompare(b.title);
  });

  fs.mkdirSync(outputDir, { recursive: true });

  for (const page of pages) {
    const outFile = path.join(outputDir, `${page.slug}.html`);
    fs.mkdirSync(path.dirname(outFile), { recursive: true });
    fs.writeFileSync(outFile, renderPage(page, pages));
  }

  fs.writeFileSync(path.join(outputDir, 'index.html'), renderIndex(pages));

  return { pages, outputDir };
}

#!/usr/bin/env node

import { buildSite } from './index';

interface CliOptions {
  content?: string;
  output?: string;
}

function printHelp(): void {
  console.log(`Usage: npx ssg build [options]

Generate a static site from Markdown files.

Options:
  --content <dir>   Content directory containing Markdown files (default: ./content)
  --output <dir>    Output directory for generated HTML (default: ./dist)
  -h, --help        Show this help message
`);
}

function parseArgs(args: string[]): CliOptions | null {
  const options: CliOptions = {};
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '-h' || arg === '--help') {
      return null;
    }
    if (arg === '--content' || arg === '--output') {
      const value = args[i + 1];
      if (value === undefined || value.startsWith('--')) {
        console.error(`Error: option ${arg} requires a value`);
        process.exit(2);
      }
      if (arg === '--content') options.content = value;
      else options.output = value;
      i++;
      continue;
    }
    if (arg.startsWith('--content=')) {
      options.content = arg.slice('--content='.length);
      continue;
    }
    if (arg.startsWith('--output=')) {
      options.output = arg.slice('--output='.length);
      continue;
    }
    console.error(`Error: unknown option ${arg}`);
    process.exit(2);
  }
  return options;
}

function main(): void {
  const args = process.argv.slice(2);
  const command = args[0];

  if (!command || command === '-h' || command === '--help' || command === 'help') {
    printHelp();
    process.exit(command && command !== 'build' ? 0 : 0);
  }

  if (command !== 'build') {
    console.error(`Error: unknown command "${command}"`);
    printHelp();
    process.exit(1);
  }

  const options = parseArgs(args.slice(1));
  if (options === null) {
    printHelp();
    process.exit(0);
  }

  const site = buildSite({
    contentDir: options.content ?? 'content',
    outputDir: options.output ?? 'dist',
  });

  console.log(`Generated ${site.pages.length} page(s) in ${site.outputDir}`);
}

main();

